import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as o,o as n,c as a,ak as r}from"./chunks/framework.DC-k2h36.js";const i="/projects/esp32Sensor/en/latest/assets/1.UFBnRk92.webp",l="/projects/esp32Sensor/en/latest/assets/0.BjYK-g_x.webp",s="/projects/esp32Sensor/en/latest/assets/2.fd8W0eD8.webp",c="/projects/esp32Sensor/en/latest/assets/3.CSyHg_aW.webp",h="/projects/esp32Sensor/en/latest/assets/4.BNLWVQWT.webp",d="/projects/esp32Sensor/en/latest/assets/5.vURV1gEu.webp",x=JSON.parse('{"title":"18. 4-Channel Line Follower Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/18. 4-Channel Line Follower Sensor.md","filePath":"docs/18. 4-Channel Line Follower Sensor.md"}'),p={name:"docs/18. 4-Channel Line Follower Sensor.md"};function g(m,e,u,b,_,f){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_18-4-channel-line-follower-sensor" tabindex="-1">18. 4-Channel Line Follower Sensor <a class="header-anchor" href="#_18-4-channel-line-follower-sensor" aria-label="Permalink to &quot;18. 4-Channel Line Follower Sensor&quot;">​</a></h1><h2 id="_18-1-introduction" tabindex="-1">18.1 Introduction <a class="header-anchor" href="#_18-1-introduction" aria-label="Permalink to &quot;18.1 Introduction&quot;">​</a></h2><p>The 4-channel line follower sensor supports one-click calibration to track lines accurately and complete complex navigation tasks. Four detector probes on the bottom compare reflected light from the surface, helping a robot car clearly tell a black line apart from a white background.</p><img loading="lazy" height="1008" width="2080" src="'+i+'" class="common_img" style="width:300px;"><h2 id="_18-2-technical-specifications" tabindex="-1">18.2 Technical Specifications <a class="header-anchor" href="#_18-2-technical-specifications" aria-label="Permalink to &quot;18.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Calibration method</td><td style="text-align:center;">One-click calibration</td></tr><tr><td style="text-align:center;">Effective range</td><td style="text-align:center;">8–16 mm</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">71.7 × 31.2 × 12.5 mm</td></tr></tbody></table><h2 id="_18-3-calibration-method" tabindex="-1">18.3 Calibration Method <a class="header-anchor" href="#_18-3-calibration-method" aria-label="Permalink to &quot;18.3 Calibration Method&quot;">​</a></h2><p>The 4-channel line follower sensor learns the map background and the line-following track, representing the black path, through its onboard calibration button. Complete the calibration process using the following steps:</p><img loading="lazy" height="901" width="1440" src="'+l+'" class="common_img" style="width:500px;"><ol><li><p>Place the probes of the 4-channel line follower sensor over the map background, then long-press the calibration button until indicator LEDs 1 and 4 flash.</p></li><li><p>When indicator LEDs 1 through 4 all flash together, place the sensor directly over the black line, then press the calibration button.</p></li><li><p>The two center indicator LEDs flash first. Once all four LEDs stay solidly lit, calibration of the 4-channel line follower sensor is complete.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Maintain a probe height between 8–16 mm off the ground during use. When a probe detects the line-following track, its corresponding indicator LED lights up.</strong></p></div><h2 id="_18-4-hands-on-project" tabindex="-1">18.4 Hands-On Project <a class="header-anchor" href="#_18-4-hands-on-project" aria-label="Permalink to &quot;18.4 Hands-On Project&quot;">​</a></h2><h3 id="_18-4-1-project-overview" tabindex="-1">18.4.1 Project Overview <a class="header-anchor" href="#_18-4-1-project-overview" aria-label="Permalink to &quot;18.4.1 Project Overview&quot;">​</a></h3><p>This project uses the 4-channel line follower sensor to check whether channels 1 through 4 detect a black line, then prints the active channel numbers to the serial monitor. Moving the sensor across the track shows which channels trigger, explaining how multi-channel line sensors detect signals.</p><h3 id="_18-4-2-hardware-wiring" tabindex="-1">18.4.2 Hardware Wiring <a class="header-anchor" href="#_18-4-2-hardware-wiring" aria-label="Permalink to &quot;18.4.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the 4-channel line follower sensor to port <strong>P1</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="910" src="'+s+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P1, P2, P3, or P4 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_18-4-3-adding-extensions" tabindex="-1">18.4.3 Adding Extensions <a class="header-anchor" href="#_18-4-3-adding-extensions" aria-label="Permalink to &quot;18.4.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>4-ch line follower sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+c+'" class="common_img" style="width:800px;"><h3 id="_18-4-4-complete-program-and-analysis" tabindex="-1">18.4.4 Complete Program and Analysis <a class="header-anchor" href="#_18-4-4-complete-program-and-analysis" aria-label="Permalink to &quot;18.4.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Upon start-up, the hardware port of the 4-channel line follower sensor is initialized to port P1.</p></li><li><p>Inside the main program loop, the detection status of channels 1 through 4 is evaluated in sequence.</p></li><li><p>When a channel identifies the black line, the program prints the corresponding channel number to the serial monitor.</p></li><li><p>A 1 s delay refreshes detection data regularly, monitoring probe states continuously.</p></li></ol><img loading="lazy" height="760" width="636" src="'+h+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">Program Files/18 4-Channel Line Follower Sensor.sb3</a>.</strong></p></div><h3 id="_18-4-5-program-upload" tabindex="-1">18.4.5 Program Upload <a class="header-anchor" href="#_18-4-5-program-upload" aria-label="Permalink to &quot;18.4.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_18-4-6-program-outcome" tabindex="-1">18.4.6 Program Outcome <a class="header-anchor" href="#_18-4-6-program-outcome" aria-label="Permalink to &quot;18.4.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, open the serial monitor in the lower-right corner of the programming software. When moving the 4-channel line follower sensor across the black line, the serial monitor prints the number of any probe that detects the path. When multiple probes sit over the line at once, their numbers print in order, clearly showing which probes are active.</p><img loading="lazy" height="904" width="1079" src="'+d+'" class="common_img" style="width:500px;">',31)])])}const k=o(p,[["render",g]]);export{x as __pageData,k as default};
